/**
 * Unit tests for _getThreePanelHtmlContent() method in GitToolWindowProvider.
 *
 * Verifies the 3-panel flexbox layout HTML structure, CSS, and JS
 * generated by the new method.
 *
 * Requirements: 1.1, 1.2, 1.5
 */

import '../../../test/setup';
import * as assert from 'assert';
import { GitToolWindowProvider } from '../../../services/GitToolWindowProvider';
import { IBranchPanelData, ICommitDetails } from '../../../services/interfaces';
import { IBranch } from '../../../services/interfaces/IGitService';
import { Uri, Webview } from '../../mocks/vscode';

/**
 * Helper to create a minimal IBranch for testing.
 */
function makeBranch(name: string, type: 'local' | 'remote' = 'local'): IBranch {
  return {
    name,
    type,
    commit: 'abc1234567890',
    isHead: false,
  };
}

/**
 * Helper to create minimal branch panel data.
 */
function makeDefaultBranchData(): IBranchPanelData {
  return {
    head: { name: 'main', isDetached: false },
    local: [makeBranch('main'), makeBranch('develop')],
    remote: [
      {
        remoteName: 'origin',
        branches: [makeBranch('origin/main', 'remote')],
      },
    ],
  };
}

/**
 * Helper to create minimal commit details.
 */
function makeCommitDetails(): ICommitDetails {
  return {
    hash: 'abc1234567890abcdef1234567890abcdef123456',
    message: 'Initial commit',
    author: { name: 'Test Author', email: 'test@example.com' },
    date: new Date('2024-01-15T10:30:00Z'),
    parents: [],
    branches: ['main'],
    tags: ['v1.0.0'],
    changedFiles: [
      { path: 'src/index.ts', status: 'added' },
      { path: 'README.md', status: 'modified' },
    ],
  };
}

/**
 * Create a mock Webview object for testing.
 */
function createMockWebview(): Webview {
  return {
    html: '',
    options: {},
    cspSource: 'https://mock.csp.source',
    onDidReceiveMessage: () => ({ dispose: () => {} }),
    postMessage: () => Promise.resolve(true),
    asWebviewUri: (uri: Uri) => uri,
  } as unknown as Webview;
}

describe('GitToolWindowProvider - _getThreePanelHtmlContent()', () => {
  let provider: GitToolWindowProvider;
  let mockWebview: Webview;

  beforeEach(() => {
    const extensionUri = Uri.file('/test/extension');
    provider = new GitToolWindowProvider(extensionUri);
    mockWebview = createMockWebview();
  });

  afterEach(() => {
    provider.dispose();
  });

  describe('Requirement 1.1: Three panels arranged horizontally', () => {
    it('should contain exactly three panel containers as direct children of the layout', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(html.includes('id="branch-panel"'), 'Should contain branch-panel');
      assert.ok(html.includes('id="graph-panel"'), 'Should contain graph-panel');
      assert.ok(html.includes('id="details-panel"'), 'Should contain details-panel');
    });

    it('should arrange panels in left-to-right order: branch, graph, details', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      const branchIndex = html.indexOf('id="branch-panel"');
      const graphIndex = html.indexOf('id="graph-panel"');
      const detailsIndex = html.indexOf('id="details-panel"');

      assert.ok(branchIndex < graphIndex, 'Branch panel should come before graph panel');
      assert.ok(graphIndex < detailsIndex, 'Graph panel should come before details panel');
    });

    it('should use a flexbox row layout container', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(html.includes('class="three-panel-layout"'), 'Should have three-panel-layout class');
      assert.ok(html.includes('flex-direction: row'), 'Should use flex-direction: row');
    });

    it('should include two draggable divider elements between panels', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(html.includes('data-divider="0"'), 'Should have first divider (index 0)');
      assert.ok(html.includes('data-divider="1"'), 'Should have second divider (index 1)');

      // Dividers should have separator role for accessibility
      const dividerMatches = html.match(/class="panel-divider"/g);
      assert.ok(dividerMatches, 'Should have panel-divider elements');
      assert.strictEqual(dividerMatches!.length, 2, 'Should have exactly 2 dividers');
    });

    it('should place dividers between the correct panels', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      const branchEnd = html.indexOf('</div>', html.indexOf('id="branch-panel"'));
      const divider0 = html.indexOf('data-divider="0"');
      const graphStart = html.indexOf('id="graph-panel"');
      const divider1 = html.indexOf('data-divider="1"');
      const detailsStart = html.indexOf('id="details-panel"');

      // Divider 0 should be between branch and graph
      assert.ok(divider0 > branchEnd, 'Divider 0 should be after branch panel');
      assert.ok(divider0 < graphStart, 'Divider 0 should be before graph panel');

      // Divider 1 should be between graph and details
      assert.ok(divider1 > graphStart, 'Divider 1 should be after graph panel start');
      assert.ok(divider1 < detailsStart, 'Divider 1 should be before details panel');
    });

    it('should have role="application" on the layout container', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(html.includes('role="application"'), 'Layout should have application role');
    });

    it('should have role="separator" on dividers', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(html.includes('role="separator"'), 'Dividers should have separator role');
    });
  });

  describe('Requirement 1.2: Default panel widths', () => {
    it('should use default widths [20%, 50%, 30%] when no widths specified', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(html.includes('style="width: 20%;"'), 'Branch panel should be 20%');
      assert.ok(html.includes('style="width: 50%;"'), 'Graph panel should be 50%');
      assert.ok(html.includes('style="width: 30%;"'), 'Details panel should be 30%');
    });

    it('should use custom widths when provided', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        [],
        undefined,
        [25, 45, 30]
      );

      assert.ok(html.includes('style="width: 25%;"'), 'Branch panel should be 25%');
      assert.ok(html.includes('style="width: 45%;"'), 'Graph panel should be 45%');
      assert.ok(html.includes('style="width: 30%;"'), 'Details panel should be 30%');
    });
  });

  describe('Requirement 1.5: Vertical stacking at < 500px', () => {
    it('should include CSS for vertical stacking', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(
        html.includes('vertical-layout'),
        'Should include vertical-layout CSS class'
      );
      assert.ok(
        html.includes('flex-direction: column'),
        'Should include column flex-direction for vertical stacking'
      );
    });

    it('should include JS-based width check for vertical stacking', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(
        html.includes('checkVerticalLayout'),
        'Should include JS function for vertical layout check'
      );
      assert.ok(
        html.includes('500'),
        'Should reference 500px threshold'
      );
    });
  });

  describe('Panel content rendering', () => {
    it('should render branch panel content from _getBranchPanelHtml()', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      // Branch panel should contain the branch tree
      assert.ok(html.includes('HEAD (Current Branch)'), 'Should render HEAD category');
      assert.ok(html.includes('data-category="local"'), 'Should render Local category');
      assert.ok(html.includes('data-category="remote"'), 'Should render Remote category');
    });

    it('should render graph panel content from _getGraphPanelHtml()', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      // Graph panel should contain the graph panel div
      assert.ok(html.includes('class="graph-panel"'), 'Should render graph panel');
    });

    it('should render details placeholder when no commit details provided', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(
        html.includes('Select a commit to view details'),
        'Should show placeholder when no commit selected'
      );
    });

    it('should render commit details when provided', () => {
      const branchData = makeDefaultBranchData();
      const commitDetails = makeCommitDetails();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        [],
        commitDetails
      );

      assert.ok(
        html.includes('Initial commit'),
        'Should render commit message'
      );
      assert.ok(
        html.includes('Test Author'),
        'Should render author name'
      );
      assert.ok(
        html.includes('abc1234567890abcdef1234567890abcdef123456'),
        'Should render full hash'
      );
    });
  });

  describe('HTML document structure', () => {
    it('should produce a complete HTML document', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(html.includes('<!DOCTYPE html>'), 'Should start with DOCTYPE');
      assert.ok(html.includes('<html lang="en">'), 'Should have html tag with lang');
      assert.ok(html.includes('<head>'), 'Should have head tag');
      assert.ok(html.includes('</head>'), 'Should close head tag');
      assert.ok(html.includes('<body>'), 'Should have body tag');
      assert.ok(html.includes('</body>'), 'Should close body tag');
      assert.ok(html.includes('</html>'), 'Should close html tag');
    });

    it('should include Content-Security-Policy meta tag', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(
        html.includes('Content-Security-Policy'),
        'Should include CSP meta tag'
      );
      assert.ok(
        html.includes(mockWebview.cspSource),
        'Should reference webview CSP source'
      );
    });

    it('should include a nonce for script security', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(html.includes('nonce-'), 'Should include nonce in CSP');
      // Script tag should have the nonce attribute
      const nonceMatch = html.match(/nonce="([^"]+)"/);
      assert.ok(nonceMatch, 'Should have nonce attribute on script tag');
    });

    it('should include inline styles', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(html.includes('<style>'), 'Should have style tag');
      assert.ok(html.includes('</style>'), 'Should close style tag');
    });

    it('should include inline script', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(html.includes('<script'), 'Should have script tag');
      assert.ok(html.includes('</script>'), 'Should close script tag');
    });
  });

  describe('Divider drag functionality', () => {
    it('should include divider drag script', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(
        html.includes('mousedown'),
        'Should include mousedown handler for drag'
      );
      assert.ok(
        html.includes('mousemove'),
        'Should include mousemove handler for drag'
      );
      assert.ok(
        html.includes('mouseup'),
        'Should include mouseup handler for drag'
      );
    });

    it('should post panelResize message on drag end', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(
        html.includes("'panelResize'"),
        'Should post panelResize message type'
      );
    });

    it('should enforce minimum panel width of 100px in drag script', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(
        html.includes('MIN_PANEL_PX'),
        'Should reference minimum panel width constant'
      );
      assert.ok(
        html.includes('100'),
        'Should use 100px as minimum'
      );
    });

    it('should include keyboard support for divider repositioning', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(
        html.includes('ArrowLeft'),
        'Should handle ArrowLeft key'
      );
      assert.ok(
        html.includes('ArrowRight'),
        'Should handle ArrowRight key'
      );
    });
  });

  describe('CSS styling', () => {
    it('should include panel divider cursor style', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(
        html.includes('cursor: col-resize'),
        'Divider should have col-resize cursor'
      );
    });

    it('should include resizing body class styles', () => {
      const branchData = makeDefaultBranchData();
      const html = provider._getThreePanelHtmlContent(
        mockWebview as unknown as import('vscode').Webview,
        branchData,
        []
      );

      assert.ok(
        html.includes('body.resizing'),
        'Should include resizing body class'
      );
      assert.ok(
        html.includes('user-select: none'),
        'Should disable text selection during resize'
      );
    });
  });
});
